/**
 * The seat count every plan check compares against. A suspended member keeps
 * their seat; only a removed (archived) member frees it.
 */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.status, ["active", "suspended"]),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function setMemberStatus(
  orgId: OrgId,
  memberId: MemberId,
  status: MemberStatus,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ status, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

