/**
 * A suspended member keeps their role and their seat, but cannot act, be
 * assigned, be mentioned, or receive notifications until reinstated.
 */
export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(message = "That member is suspended") {
    super(message);
    this.name = "MemberSuspendedError";
  }
}

export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  return changeSuspension(actor, input, "suspended");
}

export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  return changeSuspension(actor, input, "active");
}

async function changeSuspension(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
  nextStatus: "suspended" | "active",
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (member.archivedAt !== null) {
    throw new (await import("./_support")).NotFoundError("Member", input.memberId);
  }
