async function changeSuspension(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
  nextStatus: "suspended" | "active",
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (member.archivedAt !== null) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (actor.userId === member.userId) {
    throw new Error("You cannot suspend or reinstate yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(
      `A ${actor.role} cannot suspend or reinstate a ${member.role}`,
    );
  }

  if (member.status === nextStatus) return member;
  if (nextStatus === "active" && member.status !== "suspended") return member;

  if (nextStatus === "suspended") {
    await assertLastOwnerRetained(input.orgId, input.memberId, "member");
  }

  const updated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    nextStatus,
  );

  await emit(
    nextStatus === "suspended" ? "member.suspended" : "member.reinstated",
    {
      ...actorEnvelope(actor),
      memberId: updated.id,
      userId: updated.userId,
    },
  );

  return updated;
}

